#include "simulation.hpp"
#include "surface_audio.hpp"
#include <iostream>
#include <stdexcept>
using namespace ofo;
int main(int argc,char**argv){try{Resources r(argv[1]);auto c=load_vehicle(r,3);Geometry g;g.source="tracks/forest/forest1/geometry/track_geom.w32";g.materials.push_back({"tarmac"});Mesh m;m.vertices={{{-500,0,-500}},{{500,0,-500}},{{500,0,500}},{{-500,0,500}}};m.indices={0,2,1,0,3,2};g.meshes.push_back(m);Simulation sim(g,c,translate({0,1,0}));WheelEffects fx(load_wheel_effect_config(r,g,"tracks/forest/forest1/a"));auto audio=load_surface_audio_config(r,load_wheel_effect_config(r,g,"tracks/forest/forest1/a"));size_t audio_frames=0;size_t marks=0,particles=0,contacts=0;for(int i=0;i<1000;i++){Input in;if(i>=300&&i<800)in.throttle=1;if(i>=800)in.brake=1;sim.step(in);auto s=sim.state();auto voices=surface_audio_control(audio,s.wheel_contacts);if(voices.voices.count(5)&&voices.voices[5][0]+voices.voices[5][1]>0)audio_frames++;fx.update(s.wheel_contacts,s.time,s.recovery_generation);marks=std::max(marks,fx.skid_count());particles=std::max(particles,fx.particle_count());for(auto&w:s.wheel_contacts)if(w.grounded&&w.load>0){if(w.material||std::abs(w.point.y)>.05f)throw std::runtime_error("contact material="+std::to_string(w.material)+" pointY="+std::to_string(w.point.y));contacts++;}}if(!audio_frames)throw std::runtime_error("actual simulated tarmac contacts must drive native audio");if(!marks||!particles||!contacts)throw std::runtime_error("actual contact/slip must emit skids+particles");std::cout<<"audio_frames="<<audio_frames<<" contacts="<<contacts<<" marks="<<marks<<" particles="<<particles<<'\n';}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
